import sys
from collections import defaultdict

MOD = 1000000007

def matrix_mult(A, B):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def matrix_pow(M, p):
    n = len(M)
    result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    base = M
    while p > 0:
        if p % 2 == 1:
            result = matrix_mult(result, base)
        base = matrix_mult(base, base)
        p //= 2
    return result

def count_trees(n, edges):
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    def dfs(node, parent):
        subtree_nodes = [node]
        for neighbor in adj[node]:
            if neighbor != parent:
                subtree_nodes.extend(dfs(neighbor, node))
        return subtree_nodes

    components = []
    visited = set()
    for node in range(1, n + 1):
        if node not in visited:
            component = dfs(node, -1)
            components.append(component)
            for node in component:
                visited.add(node)

    component_sizes = [len(comp) for comp in components]
    total_trees = pow(n, n - 2, MOD)

    result = [0] * n
    result[0] = 1

    for size in component_sizes:
        if size > 1:
            dp = [[0] * (size + 1) for _ in range(size + 1)]
            dp[0][0] = 1
            for i in range(1, size + 1):
                for j in range(i + 1):
                    dp[i][j] = (dp[i - 1][j - 1] * (i - 1) + dp[i - 1][j] * (size - i)) % MOD

            new_result = [0] * n
            for k in range(n):
                for j in range(k + 1):
                    new_result[k] = (new_result[k] + result[j] * dp[size][k - j + 1] * pow(size, size - 2, MOD)) % MOD
            result = new_result

    result = [total_trees - sum(result[1:]) + result[0]] + result[1:]
    return result

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    edges = [(int(input[2 * i + 1]), int(input[2 * i + 2])) for i in range(n - 1)]
    result = count_trees(n, edges)
    print(' '.join(map(str, result)))

main()
